import {houses} from './house-data.js?v=finishes6';
const $=s=>document.querySelector(s),root=$('#lot-explorer');
const lotData=await fetch('assets/geography/collection-lots.json?v=13').then(r=>r.json());
const lots=lotData.lots.map(l=>({...l,inventoryId:l.id,id:l.pinIndex}));
let house=root.dataset.selectedHouse||'a';
let engine,ready,selected=null,mode='pan',state='aerial',expanded=false,vivid=true;
const number=n=>String(n).padStart(2,'0');
for(const lot of lots){for(const target of ['#zone-list','#zone-pins']){const b=document.createElement('button');b.type='button';b.dataset.zoneLot=lot.id;b.textContent=number(lot.id);b.setAttribute('aria-label',`Seleccionar lote ${number(lot.id)}`);b.setAttribute('aria-pressed','false');if(target==='#zone-pins'){b.className='zone-pin';b.hidden=true;lot.pin=b}b.addEventListener('click',()=>select(lot.id));$(target).append(b)}}
async function start(){if(ready)return ready;ready=Promise.all([import('./cesium-explorer.js?v=sections2'),fetch('assets/geography/collection-context.json').then(r=>{if(!r.ok)throw Error('Data');return r.json()}),fetch('assets/geography/collection-elevation.json').then(r=>{if(!r.ok)throw Error('Elevation');return r.json()})]).then(async([module,data,dem])=>{engine=await module.createCesiumExplorer({container:$('#zone-canvas'),data,dem,lots,onSelect:select,onStatus:message=>$('#zone-status').textContent=message});$('#zone-loading').hidden=true;$('.zone-poster').hidden=true;return engine}).catch(error=>{console.error('Territory explorer:',error);$('#zone-loading').textContent='Vista 3D no disponible. Puedes explorar las fichas desde la lista.';$('#zone-loading').style.background='#19352dc9';$('#zone-instruction').textContent='Imagen aérea de referencia · Usa la lista para consultar los lotes del cliente.';return null});return ready}
const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){start();observer.disconnect()}},{rootMargin:'250px'});observer.observe(root);
async function select(id){selected=lots.find(l=>l.id===id);if(!selected)return;root.dataset.selectedLot=id;$('#lot-number').textContent=number(id);document.dispatchEvent(new CustomEvent('rpc:lot',{detail:id}));document.querySelectorAll('[data-zone-lot]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.zoneLot)===id)));$('#zone-title').textContent='Lote '+number(id);$('#zone-index').textContent=selected.inventoryId;$('#zone-description').textContent=selected.front.nearestStreet+' · Rainbow Park';$('#zone-parcel-id').textContent=selected.parcelId;$('#zone-pin-link').href=selected.sourceURL;$('#zone-parcel-source').href=selected.parcelSourceURL;$('#zone-parcel-note').textContent=selected.groupedParcel?'Porción de 0.24 acres · Delimitación orientativa sobre un predio catastral mayor. Se ajustará con el plano de división.':'Contorno oficial de Marion County. Fachada orientada hacia '+selected.front.nearestStreet+'.';$('#zone-parcel-note').classList.toggle('needs-review',Boolean(selected.groupedParcel));$('#zone-details').hidden=false;$('#zone-initial-note').hidden=true;$('#zone-status').textContent=`Lote ${number(id)} · ${selected.front.nearestStreet}`;setState('aerial',false);const e=await start();if(selected?.id!==id)return;e?.setHouse(house);e?.select(selected,state==='aerial');e?.setState(state);if(state!=='aerial')e?.focus(selected,105)}
function setState(value,move=true){state=value;document.querySelectorAll('[data-zone-state]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.zoneState===value)));$('#zone-house-choice').hidden=value!=='house';$('#zone-state-note').textContent={aerial:'Imagen aérea de referencia sobre el contorno catastral. La vegetación visible depende de la fecha de captura.',clean:'Visualización del lote preparado. Representa una propuesta de limpieza.',house:(house==='a'?'Casa Utah':'Casa Bell')+' · Fachada hacia la calle, sobre el lado corto. Ubicación propuesta con jardín posterior.'}[value];$('#zone-occupation').hidden=value!=='house';if(value==='house'&&selected){const h=houses[house],area=selected.provisionalBoundary?76*135*.09290304:selected.gisAreaSqFt*.09290304;$('#zone-occupation').innerHTML=`<b>Casa + espacio exterior</b><span>Base modelada: ${h.footprint.toFixed(1)} m²</span><span>Fuera de la base: ≈${(area-h.footprint).toFixed(0)} m²</span><small>Estimación sobre ${selected.provisionalBoundary?'la delimitación orientativa':'el contorno GIS'}. Incluye accesos y áreas por definir.</small>`}engine?.setState(value);if(move&&selected)engine?.focus(selected,value==='aerial'?230:105)}
document.querySelectorAll('[data-zone-house]').forEach(b=>b.onclick=()=>{house=b.dataset.zoneHouse;root.dataset.selectedHouse=house;document.dispatchEvent(new CustomEvent('rpc:home',{detail:house}));document.querySelectorAll('[data-zone-house]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));engine?.setHouse(house);$('.zone-tour-link').href='utah/?house='+(house==='a'?'utah':'bell')+'&view=living';$('.zone-tour-link').textContent='Explorar Casa '+(house==='a'?'Utah':'Bell')+' e interior ↗';setState('house',false)});
document.querySelectorAll('[data-zone-state]').forEach(b=>b.addEventListener('click',()=>setState(b.dataset.zoneState)));
document.querySelectorAll('[data-zone-mode]').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.zoneMode;document.querySelectorAll('[data-zone-mode]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#zone-instruction').textContent=mode==='pan'?'Arrastra para moverte · Dos dedos para zoom · Selecciona una parcela':'Arrastra para girar e inclinar · Usa + y − para acercarte';engine?.setMode(mode)}));
$('#zone-overview').addEventListener('click',async()=>{(await start())?.overview();$('#zone-status').textContent='Rainbow Park, Ocala · Vista general';$('#zone-topdown').setAttribute('aria-pressed','false')});
$('#zone-focus').addEventListener('click',()=>selected&&engine?.focus(selected,105));
$('#zone-prev').addEventListener('click',()=>select(!selected||selected.id===1?lots.length:selected.id-1));$('#zone-next').addEventListener('click',()=>select(!selected||selected.id===lots.length?1:selected.id+1));
for(const [id,method,value] of [['zone-zoom-in','zoom',.75],['zone-zoom-out','zoom',1.33],['zone-north','north'],['zone-tilt','tilt'],['zone-topdown','top']])$('#'+id).addEventListener('click',async()=>{const e=await start();e?.[method](value)});
function expand(on){expanded=on;root.classList.toggle('zone-expanded',on);$('#zone-expand').setAttribute('aria-pressed',String(on));$('#zone-expand').setAttribute('aria-label',on?'Cerrar vista ampliada':'Ampliar explorador');$('#zone-expand').innerHTML=on?'× <span>Cerrar</span>':'⛶ <span>Ampliar</span>';engine?.resize()}
$('#zone-expand').addEventListener('click',()=>expand(!expanded));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&expanded){expand(false);$('#zone-expand').focus()}});
$('#zone-vivid').addEventListener('click',async()=>{vivid=!vivid;$('#zone-vivid').setAttribute('aria-pressed',String(vivid));$('#zone-vivid').textContent=vivid?'Color vivo':'Color original';(await start())?.setColor(vivid)});
const landscapeMobile=matchMedia('(max-width:760px)');function adaptLandscape(){document.querySelector('.zone-landscape').open=!landscapeMobile.matches}adaptLandscape();landscapeMobile.addEventListener('change',adaptLandscape);

document.addEventListener('rpc:home',e=>{if(!['a','b'].includes(e.detail)||house===e.detail)return;house=e.detail;root.dataset.selectedHouse=house;document.querySelectorAll('[data-zone-house]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.zoneHouse===house)));engine?.setHouse(house);$('.zone-tour-link').href='utah/?house='+(house==='a'?'utah':'bell')+'&view=living';$('.zone-tour-link').textContent='Explorar Casa '+(house==='a'?'Utah':'Bell')+' e interior ↗';if(selected)setState(state,false)});
